// Пользователь прислал тезисы обычным текстовым сообщением.
// Собираем инлайн-клавиатуру выбора формата и вытаскиваем chat_id + текст.
const msg = $json.message || {};
const chatId = msg.chat && msg.chat.id;
const userId = msg.from && msg.from.id;
const userName = (msg.from && (msg.from.username || msg.from.first_name)) || '';
const brief = (msg.text || '').trim();

// Язык по языку клиента Telegram (ru → RU, иначе EN).
const lang = (msg.from && msg.from.language_code || 'ru').startsWith('ru') ? 'ru' : 'en';

const L = {
  ru: {
    empty: 'Пришлите тезисы текстом — из них соберу деловое письмо, ответ или пост.',
    pick: 'Тезисы приняты. Выберите формат:',
    letter: '✉️ Письмо',
    reply: '💬 Ответ',
    post: '📢 Пост'
  },
  en: {
    empty: 'Send your key points as text — I will turn them into a business letter, reply or post.',
    pick: 'Got your points. Choose a format:',
    letter: '✉️ Letter',
    reply: '💬 Reply',
    post: '📢 Post'
  }
}[lang];

// callback_data: fmt|<letter|reply|post>. Разбирается в ноде «Разбор callback».
const keyboard = {
  inline_keyboard: [[
    { text: L.letter, callback_data: 'fmt|letter' },
    { text: L.reply, callback_data: 'fmt|reply' },
    { text: L.post, callback_data: 'fmt|post' }
  ]]
};

return {
  json: {
    chat_id: chatId,
    user_id: userId,
    user_name: userName,
    lang,
    brief,
    text_to_send: brief ? L.pick : L.empty,
    reply_markup: brief ? JSON.stringify(keyboard) : '',
    has_brief: !!brief
  }
};

// Пользователь нажал инлайн-кнопку: выбрал формат или «Другой вариант».
const cq = $json.callback_query || {};
const chatId = cq.message && cq.message.chat && cq.message.chat.id;
const userId = cq.from && cq.from.id;
const userName = (cq.from && (cq.from.username || cq.from.first_name)) || '';
const data = cq.data || '';

// callback_data формата 'fmt|letter' | 'fmt|reply' | 'fmt|post' | 'regen'
const [action, payload] = data.split('|');
const isRegen = action === 'regen';
// При «Другой вариант» формат берём из БД (нода отдаст сохранённый format).
const format = isRegen ? null : (payload || 'letter');

return {
  json: {
    chat_id: chatId,
    user_id: userId,
    user_name: userName,
    action: action || '',
    is_regen: isRegen,
    selected_format: format
  }
};
